import { test, expect } from '@playwright/test';

test.describe('Change Billing Address During Checkout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully change billing address during checkout', async ({ page }) => {
    // Verify billing address is displayed
    const billingAddress = page.getByText('123 Main St');
    await expect(billingAddress).toBeVisible();

    // Click on billing address to open modal
    const billingAddressLink = page.getByRole('link', { name: /billing address/i });
    await billingAddressLink.click();

    // Verify billing address modal is open
    const modal = page.locator('[data-testid="billing-address-modal"]');
    await expect(modal).toBeVisible();

    // Verify address input fields are visible
    const streetInput = page.getByLabel('Street Address');
    await expect(streetInput).toBeVisible();

    // Enter new street address
    await streetInput.fill('406 Oak Ave');

    // Enter new city
    const cityInput = page.getByLabel('City');
    await cityInput.fill('Springfield');

    // Enter new zip code
    const zipInput = page.getByLabel('Zip Code');
    await zipInput.fill('62701');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify modal closes
    await expect(modal).not.toBeVisible();

    // Verify new billing address is displayed
    const updatedBillingAddress = page.getByText('406 Oak Ave');
    await expect(updatedBillingAddress).toBeVisible();

    // Verify checkout proceeds
    const continueButton = page.getByRole('button', { name: /continue/i });
    await continueButton.click();

    // Verify user is on payment step
    const paymentStep = page.getByText('Payment');
    await expect(paymentStep).toBeVisible();
  });

  test('should handle invalid billing address input and prevent saving', async ({ page }) => {
    // Verify billing address is displayed
    const billingAddress = page.getByText('123 Main St');
    await expect(billingAddress).toBeVisible();

    // Click on billing address to open modal
    const billingAddressLink = page.getByRole('link', { name: /billing address/i });
    await billingAddressLink.click();

    // Verify billing address modal is open
    const modal = page.locator('[data-testid="billing-address-modal"]');
    await expect(modal).toBeVisible();

    // Enter invalid street address (empty)
    const streetInput = page.getByLabel('Street Address');
    await streetInput.fill('');

    // Enter valid city
    const cityInput = page.getByLabel('City');
    await cityInput.fill('Springfield');

    // Enter invalid zip code (too short)
    const zipInput = page.getByLabel('Zip Code');
    await zipInput.fill('12');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify validation error message appears
    const errorMessage = page.getByText('Please enter a valid zip code');
    await expect(errorMessage).toBeVisible();

    // Verify modal remains open
    await expect(modal).toBeVisible();

    // Verify billing address has not changed
    const originalBillingAddress = page.getByText('123 Main St');
    await expect(originalBillingAddress).toBeVisible();

    // Verify user is still on checkout page
    const checkoutHeader = page.getByText('Checkout');
    await expect(checkoutHeader).toBeVisible();
  });
});
